import React from 'react';

// ── Container ──

/** Size preset for the Container. */
export type ContainerSize = 'narrow' | 'wide' | 'full';

/** Props for the {@link Container} component. */
export interface ContainerProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Max-width preset. */
  size?: ContainerSize;
  /** Additional CSS class names. */
  className?: string;
  children?: React.ReactNode;
}

/**
 * Centered content container with configurable max-width.
 * Renders a `<div>` with `sk-container`.
 */
export const Container = React.forwardRef<HTMLDivElement, ContainerProps>(
  ({ size, className, children, ...rest }, ref) => (
    <div
      ref={ref}
      className={`sk-container${className ? ` ${className}` : ''}`}
      data-size={size}
      {...rest}
    >
      {children}
    </div>
  ),
);

Container.displayName = 'Container';

// ── Grid ──

/** Column count for the Grid. */
export type GridCols = '2' | '3' | '4';

/** Props for the {@link Grid} component. */
export interface GridProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Number of grid columns. */
  cols?: GridCols;
  /** Additional CSS class names. */
  className?: string;
  children?: React.ReactNode;
}

/**
 * CSS grid layout with dither hover on cells.
 * Renders a `<div>` with `sk-grid`.
 */
export const Grid = React.forwardRef<HTMLDivElement, GridProps>(
  ({ cols, className, children, ...rest }, ref) => (
    <div
      ref={ref}
      className={`sk-grid${className ? ` ${className}` : ''}`}
      data-cols={cols}
      {...rest}
    >
      {children}
    </div>
  ),
);

Grid.displayName = 'Grid';

/** Props for the {@link GridCell} sub-component. */
export interface GridCellProps extends React.HTMLAttributes<HTMLDivElement> {
  children?: React.ReactNode;
  className?: string;
}

/** Single cell within a Grid. */
export const GridCell = React.forwardRef<HTMLDivElement, GridCellProps>(
  ({ className, children, ...rest }, ref) => (
    <div ref={ref} className={`sk-grid__cell${className ? ` ${className}` : ''}`} {...rest}>
      {children}
    </div>
  ),
);

GridCell.displayName = 'GridCell';

// ── Stack ──

/** Direction for the Stack. */
export type StackDirection = 'vertical' | 'horizontal';

/** Gap size for the Stack. */
export type StackGap = 'sm' | 'lg';

/** Props for the {@link Stack} component. */
export interface StackProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Flex direction. Defaults to vertical. */
  direction?: StackDirection;
  /** Gap size override. */
  gap?: StackGap;
  /** Additional CSS class names. */
  className?: string;
  children?: React.ReactNode;
}

/**
 * Flex stack layout with optional dividers.
 * Renders a `<div>` with `sk-stack`.
 */
export const Stack = React.forwardRef<HTMLDivElement, StackProps>(
  ({ direction = 'vertical', gap, className, children, ...rest }, ref) => (
    <div
      ref={ref}
      className={`sk-stack${className ? ` ${className}` : ''}`}
      data-direction={direction}
      data-gap={gap}
      {...rest}
    >
      {children}
    </div>
  ),
);

Stack.displayName = 'Stack';

/** Props for the {@link StackDivider} sub-component. */
export interface StackDividerProps extends React.HTMLAttributes<HTMLDivElement> {
  className?: string;
}

/** Divider line between Stack items. */
export const StackDivider = React.forwardRef<HTMLDivElement, StackDividerProps>(
  ({ className, ...rest }, ref) => (
    <div ref={ref} className={`sk-stack__divider${className ? ` ${className}` : ''}`} {...rest} />
  ),
);

StackDivider.displayName = 'StackDivider';

// ── Panel ──

/** Props for the {@link Panel} component. */
export interface PanelProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Panel title shown in the header. */
  title?: string;
  /** Additional elements in the header (right side). */
  headerActions?: React.ReactNode;
  /** Additional CSS class names. */
  className?: string;
  children?: React.ReactNode;
}

/**
 * Bordered panel with header and body sections.
 * Renders a `<div>` with `sk-panel`.
 */
export const Panel = React.forwardRef<HTMLDivElement, PanelProps>(
  ({ title, headerActions, className, children, ...rest }, ref) => (
    <div ref={ref} className={`sk-panel${className ? ` ${className}` : ''}`} {...rest}>
      {title && (
        <div className="sk-panel__header">
          <h3 className="sk-panel__title">{title}</h3>
          {headerActions}
        </div>
      )}
      <div className="sk-panel__body">{children}</div>
    </div>
  ),
);

Panel.displayName = 'Panel';

// ── Divider ──

/** Variant for the Divider. */
export type DividerVariant = 'solid' | 'dashed' | 'dither' | 'ascii';

/** Props for the {@link Divider} component. */
export interface DividerProps extends React.HTMLAttributes<HTMLHRElement> {
  /** Visual variant. */
  variant?: DividerVariant;
  /** Additional CSS class names. */
  className?: string;
}

/**
 * Horizontal divider with multiple visual variants.
 * Renders an `<hr>` with `sk-divider`.
 */
export const Divider = React.forwardRef<HTMLHRElement, DividerProps>(
  ({ variant = 'solid', className, ...rest }, ref) => (
    <hr
      ref={ref}
      className={`sk-divider${className ? ` ${className}` : ''}`}
      data-variant={variant}
      {...rest}
    />
  ),
);

Divider.displayName = 'Divider';

// ── Skeleton ──

/** Shape for the Skeleton. */
export type SkeletonShape = 'circle' | 'text' | 'rect' | 'avatar';

/** Animation for the Skeleton. */
export type SkeletonAnimate = 'shimmer' | 'wave' | 'pulse';

/** Props for the {@link Skeleton} component. */
export interface SkeletonProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Shape preset. */
  shape?: SkeletonShape;
  /** Loading animation. */
  animate?: SkeletonAnimate;
  /** Explicit width CSS value. */
  width?: string | number;
  /** Explicit height CSS value. */
  height?: string | number;
  /** Additional CSS class names. */
  className?: string;
}

/**
 * Loading placeholder with dither texture.
 * Renders a `<div>` with `sk-skeleton`.
 */
export const Skeleton = React.forwardRef<HTMLDivElement, SkeletonProps>(
  ({ shape, animate, width, height, className, style, ...rest }, ref) => (
    <div
      ref={ref}
      className={`sk-skeleton${className ? ` ${className}` : ''}`}
      data-shape={shape}
      data-animate={animate}
      style={{ width, height, ...style }}
      {...rest}
    />
  ),
);

Skeleton.displayName = 'Skeleton';

/* skeehn — Container */
.sk-container { max-width: 64rem; margin: 0 auto; padding: 0 var(--sk-space-4); }
.sk-container[data-size="narrow"] { max-width: 40rem; }
.sk-container[data-size="wide"] { max-width: 80rem; }
.sk-container[data-size="full"] { max-width: 100%; padding: 0; }

/* skeehn — Grid */
.sk-grid { display: grid; gap: var(--sk-space-4); }
.sk-grid[data-cols="2"] { grid-template-columns: repeat(2, 1fr); }
.sk-grid[data-cols="3"] { grid-template-columns: repeat(3, 1fr); }
.sk-grid[data-cols="4"] { grid-template-columns: repeat(4, 1fr); }
@media (max-width: 768px) { .sk-grid { grid-template-columns: 1fr !important; } }
.sk-grid__cell { padding: var(--sk-space-4); border: var(--sk-border); border-radius: var(--sk-radius); position: relative; }
.sk-grid__cell::before { content: ""; position: absolute; inset: 0; background-image: var(--sk-dither-pattern); background-repeat: repeat; opacity: 0; pointer-events: none; transition: opacity var(--sk-transition-fast); border-radius: inherit; }
.sk-grid__cell:hover::before { opacity: calc(var(--sk-dither-opacity, 0.15) * 0.2); }
.sk-grid__cell > * { position: relative; z-index: 1; }

/* skeehn — Stack */
.sk-stack { display: flex; gap: var(--sk-space-4); }
.sk-stack[data-direction="vertical"] { flex-direction: column; }
.sk-stack[data-direction="horizontal"] { flex-direction: row; }
.sk-stack[data-gap="sm"] { gap: var(--sk-space-2); }
.sk-stack[data-gap="lg"] { gap: var(--sk-space-6); }
.sk-stack__divider { flex-shrink: 0; }
.sk-stack[data-direction="vertical"] .sk-stack__divider { width: 100%; height: 1px; background: hsl(var(--sk-border)); }
.sk-stack[data-direction="horizontal"] .sk-stack__divider { width: 1px; background: hsl(var(--sk-border)); }

/* skeehn — Panel */
.sk-panel { border: var(--sk-border); border-radius: var(--sk-radius); overflow: hidden; }
.sk-panel__header { display: flex; align-items: center; justify-content: space-between; padding: var(--sk-space-3) var(--sk-space-4); background: hsl(var(--sk-muted) / 0.5); border-bottom: var(--sk-border); }
.sk-panel__title { font-family: var(--sk-font-mono); font-size: var(--sk-font-size-sm); font-weight: 600; letter-spacing: 0.02em; text-transform: uppercase; margin: 0; }
.sk-panel__body { padding: var(--sk-space-4); position: relative; }
.sk-panel__body::before { content: ""; position: absolute; inset: 0; background-image: var(--sk-dither-pattern); background-repeat: repeat; opacity: calc(var(--sk-dither-opacity, 0.15) * 0.1); pointer-events: none; }
.sk-panel__body > * { position: relative; z-index: 1; }

/* skeehn — Divider */
.sk-divider { border: none; margin: var(--sk-space-4) 0; }
.sk-divider[data-variant="solid"] { border-top: 1px solid hsl(var(--sk-border)); }
.sk-divider[data-variant="dashed"] { border-top: 1px dashed hsl(var(--sk-border)); }
.sk-divider[data-variant="dither"] { border: none; height: 4px; background-image: var(--sk-dither-pattern); background-repeat: repeat; opacity: var(--sk-dither-opacity); border-radius: 2px; }
.sk-divider[data-variant="ascii"] { border: none; text-align: center; font-family: var(--sk-font-mono); font-size: 0.5rem; color: hsl(var(--sk-border)); letter-spacing: 0.2em; }
.sk-divider[data-variant="ascii"]::after { content: "────────────────────────────────────────"; }

/* skeehn — Skeleton */
.sk-skeleton { background: hsl(var(--sk-muted)); border-radius: var(--sk-radius); position: relative; overflow: hidden; }
.sk-skeleton::before { content: ""; position: absolute; inset: 0; background-image: var(--sk-dither-pattern); background-repeat: repeat; opacity: calc(var(--sk-dither-opacity, 0.15) * 0.3); }
.sk-skeleton[data-shape="circle"] { border-radius: var(--sk-radius-full); }
.sk-skeleton[data-shape="text"] { height: 0.875rem; }
.sk-skeleton[data-shape="rect"] { height: 6rem; }
.sk-skeleton[data-shape="avatar"] { width: 2.5rem; height: 2.5rem; border-radius: var(--sk-radius-full); }
.sk-skeleton[data-animate="shimmer"]::after { content: ""; position: absolute; inset: 0; background: linear-gradient(90deg, transparent, hsl(var(--sk-muted-foreground) / 0.1), transparent); background-size: 200% 100%; animation: sk-shimmer 1.5s ease-in-out infinite; }
.sk-skeleton[data-animate="wave"]::after { content: ""; position: absolute; inset: 0; background: linear-gradient(90deg, transparent, hsl(var(--sk-muted-foreground) / 0.08), transparent); animation: sk-wave 2s ease-in-out infinite; }
.sk-skeleton[data-animate="pulse"] { animation: sk-dither-pulse 2s ease-in-out infinite; }
